#!/usr/bin/env Rscript
# FIXED FILE: do not edit. Generated by bin/adding_method/add_method.py.
#
# Does all the file work for an R method and calls the three functions of
# <method>_core.R. Usage: messi_run.R <step> --method=NAME [--key=value ...]
# Steps: preprocess, train, predict, select_feature, check.

script_arg <- grep("^--file=", commandArgs(FALSE), value = TRUE)[1]
script_dir <- dirname(normalizePath(sub("^--file=", "", script_arg)))
source(file.path(script_dir, "messi_contract.R"))

parse_cli <- function(args) {
  opts <- list(step = args[1])
  for (arg in args[-1]) {
    parts <- regmatches(arg, regexec("^--([^=]+)=(.*)$", arg))[[1]]
    if (length(parts) != 3) stop("Cannot read argument: ", arg, call. = FALSE)
    opts[[parts[2]]] <- parts[3]
  }
  opts
}

# ---- MultiAssayExperiment to plain data (only these two steps need Bioconductor) ----

load_mae <- function(path) {
  suppressPackageStartupMessages({
    library(MultiAssayExperiment)
    library(HDF5Array)
  })
  loadHDF5MultiAssayExperiment(dir = path, prefix = "")
}

response_to_binary <- function(y) {
  if (!is.null(dim(y))) y <- y[["response"]]
  labels <- tolower(trimws(as.character(y)))
  bad <- !(labels %in% c("yes", "y", "1", "true", "no", "n", "0", "false"))
  if (any(bad)) {
    contract_fail("the response column of the data", paste(unique(labels[bad]), collapse = ", "), "yes/no or 1/0 labels")
  }
  as.integer(labels %in% c("yes", "y", "1", "true"))
}

mae_to_plain <- function(mae) {
  X <- lapply(mae@ExperimentList@listData, function(m) t(as.matrix(m)))
  y <- response_to_binary(mae$response)
  names(y) <- rownames(MultiAssayExperiment::colData(mae))
  samples <- rownames(X[[1]])
  if (all(samples %in% names(y))) y <- y[samples]
  names(y) <- samples
  data <- list(X = X, y = y)
  validate_plain_data(data, "the data loaded from the MultiAssayExperiment")
  data
}

load_test_splits <- function(split_dir) {
  files <- list.files(split_dir, pattern = "\\.txt$", full.names = TRUE)
  if (length(files) == 0) stop("No .txt fold files in ", split_dir, call. = FALSE)
  splits <- lapply(files, function(f) scan(f, what = numeric(), quiet = TRUE))
  # The splitter writes 0-based indices
  if (any(vapply(splits, function(s) any(s == 0), logical(1)))) {
    splits <- lapply(splits, function(s) s + 1)
  }
  setNames(splits, tools::file_path_sans_ext(basename(files)))
}

step_preprocess <- function(opts) {
  mae <- load_mae(opts$data_path)
  splits <- load_test_splits(opts$split_dir)
  for (fold in names(splits)) {
    test_idx <- splits[[fold]]
    dir.create(fold, showWarnings = FALSE)
    saveRDS(mae_to_plain(mae[, -test_idx, drop = TRUE]), file.path(fold, "train.rds"))
    saveRDS(mae_to_plain(mae[, test_idx, drop = TRUE]), file.path(fold, "test.rds"))
    cat("Prepared", fold, "with", length(test_idx), "test samples\n")
  }
}

# ---- The steps that call the developer's functions ----

step_train <- function(opts) {
  core <- load_core(script_dir, opts$method)
  train <- readRDS(file.path(opts$fold_path, "train.rds"))
  test <- readRDS(file.path(opts$fold_path, "test.rds"))
  seed <- seed_from_label(opts$seed_label)
  set.seed(seed)
  cat("Calling fit() on", length(train$y), "samples, seed", seed, "\n")
  model <- validate_model(core$fit(train$X, train$y, seed = seed))
  saveRDS(model, opts$model_out)
  saveRDS(test, opts$test_out)
}

step_predict <- function(opts) {
  core <- load_core(script_dir, opts$method)
  model <- readRDS(opts$model_path)
  test <- readRDS(opts$test_path)
  samples <- rownames(test$X[[1]])
  cat("Calling predict_proba() on", length(samples), "samples\n")
  phat <- validate_predictions(core$predict_proba(model, test$X), samples)
  table <- build_result_table(phat, samples, test$y, opts$method, opts$dataset, opts$fold)
  write_result_csv(table, opts$result_out)
}

step_select_feature <- function(opts) {
  core <- load_core(script_dir, opts$method)
  data <- mae_to_plain(load_mae(opts$data_path))
  seed <- seed_from_label(opts$dataset)
  set.seed(seed)
  cat("Calling fit() on all", length(data$y), "samples, seed", seed, "\n")
  model <- validate_model(core$fit(data$X, data$y, seed = seed))
  features <- validate_features(core$feature_weights(model), data$X)
  write_feature_csv(build_feature_table(features, opts$method, opts$dataset), opts$features_out)
  record <- build_hyperparameter_record(core$HYPERPARAMETERS, opts$method, opts$dataset, seed)
  write_hyperparameter_json(record, opts$hyperparameters_out)
}

# ---- Self-check on synthetic data, used by `add_method.py check` ----

synthetic_data <- function(n, seed) {
  set.seed(seed)
  samples <- sprintf("sample_%03d", seq_len(n))
  y <- as.integer(seq_len(n) %% 2 == 0)
  names(y) <- samples
  make_view <- function(p, prefix) {
    m <- matrix(rnorm(n * p), n, p, dimnames = list(samples, sprintf("%s_%02d", prefix, seq_len(p))))
    m[, 1:3] <- m[, 1:3] + 2 * y
    m
  }
  list(X = list(view_a = make_view(12, "a"), view_b = make_view(8, "b")), y = y)
}

auc <- function(y, score) {
  r <- rank(score)
  n1 <- sum(y == 1)
  n0 <- sum(y == 0)
  (sum(r[y == 1]) - n1 * (n1 + 1) / 2) / (n1 * n0)
}

check_error_hint <- function(message) {
  if (grepl("there is no package called", message)) return("Install the package, or use a container that has it.")
  if (grepl("not implemented", message)) return("Fill in this function in the core file.")
  "Fix this function in the core file. The message above says what it returned and what is expected."
}

report <- function(status, name, detail, hint = NULL) {
  cat(sprintf("  %-4s %-16s %s\n", status, name, detail))
  if (!is.null(hint)) cat(sprintf("       %-16s Fix: %s\n", "", hint))
}

report_home_packages <- function() {
  if (Sys.getenv("MESSI_CHECK_IMAGE") != "1") return(invisible())
  paths <- vapply(loadedNamespaces(), function(p) find.package(p), "")
  under_home <- names(paths)[grepl("^(/home/|/root/)", paths)]
  if (length(under_home) > 0) cat("HOME-PACKAGES:", paste(under_home, collapse = ","), "\n")
}

step_check <- function(opts) {
  core_file <- paste0(opts$method, "_core.R")
  cat(sprintf("Self-check of '%s' on synthetic data (2 views, 40 train and 12 test samples)\n", opts$method))
  failed <- FALSE
  workdir <- tempfile("messi_check")
  dir.create(workdir)
  on.exit(unlink(workdir, recursive = TRUE))

  run <- function(name, expr) {
    tryCatch(list(ok = TRUE, value = expr), error = function(e) {
      message <- conditionMessage(e)
      report("FAIL", name, gsub("\n", "\n       ", message), check_error_hint(message))
      failed <<- TRUE
      list(ok = FALSE)
    })
  }

  loaded <- run(core_file, load_core(script_dir, opts$method))
  if (!loaded$ok) {
    cat("Result: FAIL\n")
    quit(save = "no", status = 1)
  }
  core <- loaded$value
  data <- synthetic_data(52, 1)
  train_rows <- 1:40
  test_rows <- 41:52
  X_train <- lapply(data$X, function(m) m[train_rows, , drop = FALSE])
  X_test <- lapply(data$X, function(m) m[test_rows, , drop = FALSE])
  y_train <- data$y[train_rows]
  y_test <- data$y[test_rows]
  samples <- rownames(X_test[[1]])
  model_path <- file.path(workdir, "model.rds")

  set.seed(1)
  fitted <- run("fit", {
    model <- validate_model(core$fit(X_train, y_train, seed = 1L))
    saveRDS(model, model_path)
    readRDS(model_path)
  })
  if (fitted$ok) {
    report("PASS", "fit", sprintf("returned %s, saved and reloaded with saveRDS", describe(fitted$value)))
    predicted <- run("predict_proba", {
      validate_predictions(core$predict_proba(fitted$value, X_test), samples)
    })
    if (predicted$ok) {
      score <- auc(y_test, predicted$value)
      report("PASS", "predict_proba", sprintf("%d scores from %.3f to %.3f, AUC on synthetic data %.2f",
                                              length(samples), min(predicted$value), max(predicted$value), score))
      if (score < 0.5) cat("       Note: AUC below 0.5. Check that the score is the probability of class 1.\n")
    }
    weights <- run("feature_weights", validate_features(core$feature_weights(fitted$value), X_train))
    if (weights$ok) {
      report("PASS", "feature_weights", sprintf("%d rows in views: %s", nrow(weights$value),
                                                paste(unique(weights$value$view), collapse = ", ")))
    }
    if (predicted$ok && weights$ok) {
      written <- run("output files", {
        result <- build_result_table(predicted$value, samples, y_test, opts$method, "synthetic", "fold_1")
        write_result_csv(result, file.path(workdir, "result.csv"))
        write_feature_csv(build_feature_table(weights$value, opts$method, "synthetic"), file.path(workdir, "features.csv"))
        record <- build_hyperparameter_record(core$HYPERPARAMETERS, opts$method, "synthetic", 1L)
        write_hyperparameter_json(record, file.path(workdir, "hyperparameters.json"))
        TRUE
      })
      if (written$ok) report("PASS", "output files", "result table, feature table and hyperparameter JSON were written")
    }
  } else {
    report("SKIP", "predict_proba", "needs a working fit()")
    report("SKIP", "feature_weights", "needs a working fit()")
  }
  report_home_packages()
  cat(if (failed) "Result: FAIL\n" else "Result: PASS\n")
  quit(save = "no", status = if (failed) 1 else 0)
}

opts <- parse_cli(commandArgs(TRUE))
steps <- list(preprocess = step_preprocess, train = step_train, predict = step_predict,
              select_feature = step_select_feature, check = step_check)
if (is.na(opts$step) || !(opts$step %in% names(steps))) {
  stop("First argument must be one of: ", paste(names(steps), collapse = ", "), call. = FALSE)
}
steps[[opts$step]](opts)
cat("Done\n")
